EMBEDDED_SOURCES = json.loads(r"""{"ai/__init__.py": "", "ai/data.py": "\"\"\"Dataset, deterministic split, and transforms for E-IDSS.\n\nThe split is derived from sorted filenames + a fixed seed so that the local\nmachine and the Kaggle trainer produce byte-identical train/val/test sets\nwithout shipping manifests between them.\n\"\"\"\n\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\nfrom PIL import Image\nfrom torch.utils.data import Dataset\nfrom torchvision import transforms\n\nCLASSES = [\"crack\", \"hole\", \"normal\", \"rust\", \"scratch\"]\nDEFECT_CLASSES = [c for c in CLASSES if c != \"normal\"]\nNORMAL_IDX = CLASSES.index(\"normal\")\n\nIMAGENET_MEAN = [0.485, 0.456, 0.406]\nIMAGENET_STD = [0.229, 0.224, 0.225]\n\n\ndef stratified_split(root: Path, seed: int = 1337, val_frac: float = 0.15, test_frac: float = 0.15):\n    \"\"\"Return {split: [(path, label_idx)]}, stratified per class and reproducible.\"\"\"\n    rng = np.random.default_rng(seed)\n    out = {\"train\": [], \"val\": [], \"test\": []}\n\n    for label_idx, cls in enumerate(CLASSES):\n        files = sorted((root / cls).glob(\"*.png\"))\n        if not files:\n            raise FileNotFoundError(f\"no images found in {root / cls}\")\n        idx = rng.permutation(len(files))\n        n_val = int(len(files) * val_frac)\n        n_test = int(len(files) * test_frac)\n\n        for split, chunk in (\n            (\"val\", idx[:n_val]),\n            (\"test\", idx[n_val : n_val + n_test]),\n            (\"train\", idx[n_val + n_test :]),\n        ):\n            out[split].extend((files[i], label_idx) for i in chunk)\n\n    for split in out:\n        out[split].sort(key=lambda pair: str(pair[0]))\n    return out\n\n\ndef build_transforms(img_size: int = 224, train: bool = False):\n    # Source images are 256x256 grayscale; replicate to 3ch so ImageNet-pretrained\n    # weights stay usable, then normalise with the standard statistics.\n    to_rgb = transforms.Grayscale(num_output_channels=3)\n\n    if train:\n        return transforms.Compose([\n            to_rgb,\n            transforms.RandomResizedCrop(img_size, scale=(0.75, 1.0), ratio=(0.9, 1.11)),\n            transforms.RandomHorizontalFlip(),\n            transforms.RandomVerticalFlip(),\n            transforms.RandomApply([transforms.RandomRotation(20)], p=0.5),\n            transforms.ColorJitter(brightness=0.3, contrast=0.3),\n            transforms.ToTensor(),\n            transforms.Normalize(IMAGENET_MEAN, IMAGENET_STD),\n            transforms.RandomErasing(p=0.25, scale=(0.02, 0.12)),\n        ])\n\n    return transforms.Compose([\n        to_rgb,\n        transforms.Resize(img_size + 32),\n        transforms.CenterCrop(img_size),\n        transforms.ToTensor(),\n        transforms.Normalize(IMAGENET_MEAN, IMAGENET_STD),\n    ])\n\n\nclass DefectDataset(Dataset):\n    def __init__(self, samples, transform):\n        self.samples = samples\n        self.transform = transform\n\n    def __len__(self):\n        return len(self.samples)\n\n    def __getitem__(self, i):\n        path, label = self.samples[i]\n        image = Image.open(path)\n        return self.transform(image), label\n\n\ndef binary_targets(labels: torch.Tensor) -> torch.Tensor:\n    \"\"\"1 = defective, 0 = acceptable. Drives false-accept / false-reject metrics.\"\"\"\n    return (labels != NORMAL_IDX).long()\n", "ai/model.py": "\"\"\"Backbone wrapper exposing logits and penultimate features.\n\nThe features are needed twice downstream: for the Mahalanobis OOD gate and for\nGrad-CAM++ saliency, so the model returns them rather than hiding them.\n\"\"\"\n\nimport torch\nimport torch.nn as nn\nfrom torchvision import models\n\nfrom ai.data import CLASSES\n\n\nclass DefectNet(nn.Module):\n    def __init__(self, arch: str = \"convnext_tiny\", num_classes: int = len(CLASSES), pretrained: bool = True):\n        super().__init__()\n        self.arch = arch\n\n        if arch == \"convnext_tiny\":\n            weights = models.ConvNeXt_Tiny_Weights.IMAGENET1K_V1 if pretrained else None\n            net = models.convnext_tiny(weights=weights)\n            self.features = net.features\n            self.norm = net.classifier[0]\n            self.pool = nn.AdaptiveAvgPool2d(1)\n            self.feat_dim = net.classifier[2].in_features\n        elif arch == \"efficientnet_v2_s\":\n            weights = models.EfficientNet_V2_S_Weights.IMAGENET1K_V1 if pretrained else None\n            net = models.efficientnet_v2_s(weights=weights)\n            self.features = net.features\n            self.norm = nn.Identity()\n            self.pool = nn.AdaptiveAvgPool2d(1)\n            self.feat_dim = net.classifier[1].in_features\n        else:\n            raise ValueError(f\"unsupported arch {arch!r}\")\n\n        self.dropout = nn.Dropout(p=0.3)\n        self.head = nn.Linear(self.feat_dim, num_classes)\n\n    def forward_features(self, x):\n        \"\"\"Spatial feature map \u2014 Grad-CAM++ hooks here.\"\"\"\n        return self.features(x)\n\n    def forward(self, x, return_features: bool = False):\n        fmap = self.features(x)\n        pooled = self.pool(self.norm(fmap)).flatten(1)\n        logits = self.head(self.dropout(pooled))\n        if return_features:\n            return logits, pooled\n        return logits\n\n    def enable_mc_dropout(self):\n        \"\"\"Keep dropout active at eval time for epistemic uncertainty sampling.\"\"\"\n        self.dropout.train()\n\n\ndef load_for_inference(checkpoint_path, device=\"cuda\"):\n    ckpt = torch.load(checkpoint_path, map_location=device, weights_only=False)\n    model = DefectNet(arch=ckpt.get(\"arch\", \"convnext_tiny\"), pretrained=False)\n    model.load_state_dict(ckpt[\"state_dict\"])\n    model.to(device).eval()\n    return model, ckpt\n", "ai/robustness.py": "\"\"\"Deliberately shifted evaluation conditions.\n\nThe rubric scores 'robustness to unseen conditions' (lighting / orientation /\nbatch change). None of that exists in the provided data, so we synthesise the\nshifts at eval time and report accuracy per condition. Shifts are applied to\nthe held-out test split only -- never seen during training.\n\"\"\"\n\nfrom PIL import Image, ImageEnhance, ImageFilter\nfrom torchvision import transforms\n\nfrom ai.data import IMAGENET_MEAN, IMAGENET_STD\n\n\ndef _brightness(factor):\n    return lambda im: ImageEnhance.Brightness(im).enhance(factor)\n\n\ndef _contrast(factor):\n    return lambda im: ImageEnhance.Contrast(im).enhance(factor)\n\n\ndef _blur(radius):\n    return lambda im: im.filter(ImageFilter.GaussianBlur(radius))\n\n\ndef _rotate(degrees):\n    return lambda im: im.rotate(degrees, resample=Image.BILINEAR, fillcolor=0)\n\n\ndef _compose(*fns):\n    def apply(im):\n        for fn in fns:\n            im = fn(im)\n        return im\n    return apply\n\n\n# Each entry is a named, physically-motivated shift a real line would produce.\nCONDITIONS = {\n    \"clean\": lambda im: im,\n    \"bright_lighting\": _brightness(1.45),\n    \"dim_lighting\": _brightness(0.6),\n    \"low_contrast\": _contrast(0.55),\n    \"rotated_15deg\": _rotate(15),\n    \"rotated_90deg\": _rotate(90),\n    \"defocus_blur\": _blur(1.6),\n    \"combined_hard\": _compose(_brightness(1.3), _contrast(0.7), _rotate(12), _blur(1.0)),\n}\n\n\ndef build_condition_transform(condition: str, img_size: int = 224):\n    if condition not in CONDITIONS:\n        raise KeyError(f\"unknown condition {condition!r}; have {list(CONDITIONS)}\")\n    return transforms.Compose([\n        transforms.Grayscale(num_output_channels=3),\n        transforms.Lambda(CONDITIONS[condition]),\n        transforms.Resize(img_size + 32),\n        transforms.CenterCrop(img_size),\n        transforms.ToTensor(),\n        transforms.Normalize(IMAGENET_MEAN, IMAGENET_STD),\n    ])\n", "ai/explain.py": "\"\"\"Grad-CAM++ saliency and the trust gate (Mahalanobis OOD + MC-dropout).\n\nLocalization is scored on heatmap quality and the dataset ships no boxes or\nmasks, so the heatmap is the localization output. A box is derived from it by\nthresholding, which is honest about its provenance: it is a heatmap-derived\nregion, not a learned detection.\n\"\"\"\n\nimport numpy as np\nimport torch\nimport torch.nn.functional as F\n\nfrom ai.data import CLASSES, NORMAL_IDX\n\n\nclass GradCAMPlusPlus:\n    \"\"\"Grad-CAM++ on the final conv stage. CNN backbone keeps this clean.\"\"\"\n\n    def __init__(self, model, target_layer=None):\n        self.model = model\n        self.activations = None\n        self.gradients = None\n        layer = target_layer if target_layer is not None else model.features[-1]\n        layer.register_forward_hook(self._save_activation)\n        layer.register_full_backward_hook(self._save_gradient)\n\n    def _save_activation(self, _module, _inp, out):\n        self.activations = out\n\n    def _save_gradient(self, _module, _grad_in, grad_out):\n        self.gradients = grad_out[0]\n\n    def __call__(self, x, class_idx=None):\n        self.model.zero_grad(set_to_none=True)\n        logits = self.model(x)\n        if class_idx is None:\n            class_idx = int(logits.argmax(1).item())\n        logits[:, class_idx].sum().backward()\n\n        grads, acts = self.gradients, self.activations\n        grads_pow2 = grads.pow(2)\n        grads_pow3 = grads_pow2 * grads\n        sum_acts = acts.sum(dim=(2, 3), keepdim=True)\n        denom = 2 * grads_pow2 + sum_acts * grads_pow3\n        alpha = grads_pow2 / torch.where(denom != 0, denom, torch.ones_like(denom))\n        weights = (alpha * F.relu(grads)).sum(dim=(2, 3), keepdim=True)\n\n        cam = F.relu((weights * acts).sum(dim=1, keepdim=True))\n        cam = F.interpolate(cam, size=x.shape[-2:], mode=\"bilinear\", align_corners=False)\n        cam = cam.squeeze().detach().cpu().numpy()\n        if cam.max() > cam.min():\n            cam = (cam - cam.min()) / (cam.max() - cam.min())\n        return cam, class_idx\n\n\ndef heatmap_to_box(cam: np.ndarray, threshold: float = 0.5):\n    \"\"\"Tightest box around the region above `threshold` of peak activation.\"\"\"\n    mask = cam >= threshold\n    if not mask.any():\n        return None\n    ys, xs = np.where(mask)\n    h, w = cam.shape\n    return {\n        \"x\": int(xs.min()), \"y\": int(ys.min()),\n        \"width\": int(xs.max() - xs.min() + 1),\n        \"height\": int(ys.max() - ys.min() + 1),\n        \"image_width\": int(w), \"image_height\": int(h),\n        \"coverage\": float(mask.mean()),\n    }\n\n\nclass TrustGate:\n    \"\"\"Decides predict-vs-defer. Two independent signals must both pass.\"\"\"\n\n    def __init__(self, means, precision, temperature=1.0, mahalanobis_threshold=None):\n        self.means = means\n        self.precision = precision\n        self.temperature = float(temperature)\n        self.mahalanobis_threshold = mahalanobis_threshold\n\n    def mahalanobis(self, feats: torch.Tensor) -> torch.Tensor:\n        \"\"\"Min distance to any class centroid \u2014 high means off-manifold.\"\"\"\n        diffs = feats.unsqueeze(1) - self.means.unsqueeze(0).to(feats.device)\n        precision = self.precision.to(feats.device)\n        dist = torch.einsum(\"bcf,fg,bcg->bc\", diffs, precision, diffs)\n        return dist.clamp(min=0).sqrt().min(dim=1).values\n\n    @torch.no_grad()\n    def mc_dropout(self, model, x, passes: int = 20):\n        \"\"\"Epistemic uncertainty as predictive variance across dropout samples.\"\"\"\n        model.eval()\n        model.enable_mc_dropout()\n        probs = torch.stack([\n            F.softmax(model(x) / self.temperature, dim=1) for _ in range(passes)\n        ])\n        model.eval()\n        mean = probs.mean(0)\n        return mean, probs.var(0).sum(1)\n\n    @torch.no_grad()\n    def assess(self, model, x, passes: int = 20):\n        logits, feats = model(x, return_features=True)\n        calibrated = F.softmax(logits / self.temperature, dim=1)\n        mean_probs, epistemic = self.mc_dropout(model, x, passes)\n        distance = self.mahalanobis(feats)\n\n        pred = int(mean_probs.argmax(1).item())\n        confidence = float(mean_probs.max(1).values.item())\n        dist_value = float(distance.item())\n        is_ood = (\n            self.mahalanobis_threshold is not None\n            and dist_value > self.mahalanobis_threshold\n        )\n        low_confidence = confidence < 0.65\n\n        return {\n            \"predicted_class\": CLASSES[pred],\n            \"predicted_index\": pred,\n            \"is_defective\": pred != NORMAL_IDX,\n            \"calibrated_confidence\": confidence,\n            \"raw_confidence\": float(calibrated.max(1).values.item()),\n            \"epistemic_uncertainty\": float(epistemic.item()),\n            \"mahalanobis_distance\": dist_value,\n            \"mahalanobis_threshold\": self.mahalanobis_threshold,\n            \"novel_or_uncertain\": bool(is_ood or low_confidence),\n            \"decision\": \"DEFER_TO_HUMAN\" if (is_ood or low_confidence) else \"AUTO\",\n            \"class_probabilities\": {\n                CLASSES[i]: float(mean_probs[0, i]) for i in range(len(CLASSES))\n            },\n        }\n", "ai/train.py": "\"\"\"Train the defect classifier. Designed to run on Kaggle's 2x T4 accelerator.\n\nSaves a single checkpoint carrying everything inference needs: weights, the\nfitted Mahalanobis OOD statistics, calibration temperature, and the full\nmetrics report (clean + per-shift robustness).\n\n    python -m ml.train --data-root train/train --epochs 15\n\"\"\"\n\nimport argparse\nimport json\nimport time\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nfrom sklearn.metrics import classification_report, confusion_matrix, f1_score\nfrom torch.utils.data import DataLoader\n\nfrom ai.data import CLASSES, NORMAL_IDX, DefectDataset, build_transforms, stratified_split\nfrom ai.model import DefectNet\nfrom ai.robustness import CONDITIONS, build_condition_transform\n\n\ndef loaders(splits, img_size, batch_size, workers):\n    train_ds = DefectDataset(splits[\"train\"], build_transforms(img_size, train=True))\n    val_ds = DefectDataset(splits[\"val\"], build_transforms(img_size, train=False))\n    common = dict(num_workers=workers, pin_memory=True, persistent_workers=workers > 0)\n    return (\n        DataLoader(train_ds, batch_size=batch_size, shuffle=True, drop_last=True, **common),\n        DataLoader(val_ds, batch_size=batch_size * 2, shuffle=False, **common),\n    )\n\n\n@torch.no_grad()\ndef evaluate(model, loader, device):\n    model.eval()\n    logits_all, labels_all = [], []\n    for images, labels in loader:\n        images = images.to(device, non_blocking=True)\n        with torch.autocast(\"cuda\", dtype=torch.float16, enabled=device.type == \"cuda\"):\n            logits = model(images)\n        logits_all.append(logits.float().cpu())\n        labels_all.append(labels)\n    return torch.cat(logits_all), torch.cat(labels_all)\n\n\ndef fit_temperature(logits, labels):\n    \"\"\"Temperature scaling \u2014 calibrated confidence is an explicit rubric item.\"\"\"\n    log_t = torch.zeros(1, requires_grad=True)\n    optimizer = torch.optim.LBFGS([log_t], lr=0.1, max_iter=60)\n\n    def closure():\n        optimizer.zero_grad()\n        loss = F.cross_entropy(logits / log_t.exp(), labels)\n        loss.backward()\n        return loss\n\n    optimizer.step(closure)\n    return float(log_t.exp().item())\n\n\n@torch.no_grad()\ndef fit_mahalanobis(model, loader, device, feat_dim):\n    \"\"\"Per-class means + shared shrunk covariance over training features.\"\"\"\n    model.eval()\n    sums = torch.zeros(len(CLASSES), feat_dim, dtype=torch.float64)\n    counts = torch.zeros(len(CLASSES), dtype=torch.float64)\n    feats_all, labels_all = [], []\n\n    for images, labels in loader:\n        images = images.to(device, non_blocking=True)\n        with torch.autocast(\"cuda\", dtype=torch.float16, enabled=device.type == \"cuda\"):\n            _, feats = model(images, return_features=True)\n        feats = feats.float().cpu().double()\n        feats_all.append(feats)\n        labels_all.append(labels)\n        for c in range(len(CLASSES)):\n            mask = labels == c\n            if mask.any():\n                sums[c] += feats[mask].sum(0)\n                counts[c] += int(mask.sum())\n\n    means = sums / counts.unsqueeze(1).clamp(min=1)\n    feats_all = torch.cat(feats_all)\n    labels_all = torch.cat(labels_all)\n    centered = feats_all - means[labels_all]\n    cov = (centered.T @ centered) / max(len(feats_all) - len(CLASSES), 1)\n    cov += torch.eye(feat_dim, dtype=torch.float64) * 1e-3  # shrinkage keeps the inverse stable\n    return means, torch.linalg.inv(cov)\n\n\ndef report(logits, labels, temperature=1.0):\n    probs = F.softmax(logits / temperature, dim=1)\n    preds = probs.argmax(1)\n    binary_true = (labels != NORMAL_IDX).long()\n    binary_pred = (preds != NORMAL_IDX).long()\n\n    false_accept = int(((binary_true == 1) & (binary_pred == 0)).sum())  # defect shipped\n    false_reject = int(((binary_true == 0) & (binary_pred == 1)).sum())  # good part scrapped\n    n_defect = int((binary_true == 1).sum())\n    n_normal = int((binary_true == 0).sum())\n\n    return {\n        \"accuracy\": float((preds == labels).float().mean()),\n        \"macro_f1\": float(f1_score(labels, preds, average=\"macro\")),\n        \"per_class\": classification_report(\n            labels, preds, target_names=CLASSES, output_dict=True, zero_division=0\n        ),\n        \"confusion_matrix\": confusion_matrix(labels, preds).tolist(),\n        \"false_accept_count\": false_accept,\n        \"false_reject_count\": false_reject,\n        \"false_accept_rate\": false_accept / max(n_defect, 1),\n        \"false_reject_rate\": false_reject / max(n_normal, 1),\n        \"mean_confidence\": float(probs.max(1).values.mean()),\n    }\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--data-root\", default=\"train/train\")\n    parser.add_argument(\"--arch\", default=\"convnext_tiny\")\n    parser.add_argument(\"--epochs\", type=int, default=15)\n    parser.add_argument(\"--batch-size\", type=int, default=64)\n    parser.add_argument(\"--lr\", type=float, default=3e-4)\n    parser.add_argument(\"--img-size\", type=int, default=224)\n    parser.add_argument(\"--workers\", type=int, default=4)\n    parser.add_argument(\"--seed\", type=int, default=1337)\n    parser.add_argument(\"--out\", default=\"models/convnext_tiny_eidss.pt\")\n    args = parser.parse_args()\n\n    torch.manual_seed(args.seed)\n    np.random.seed(args.seed)\n    device = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\n    n_gpu = torch.cuda.device_count()\n    print(f\"device={device} gpus={n_gpu} \" + \", \".join(\n        torch.cuda.get_device_name(i) for i in range(n_gpu)\n    ))\n\n    splits = stratified_split(Path(args.data_root), seed=args.seed)\n    print({k: len(v) for k, v in splits.items()})\n\n    # DataParallel splits each batch across both T4s; scale batch so per-GPU work\n    # stays sensible.\n    effective_batch = args.batch_size * max(n_gpu, 1)\n    train_loader, val_loader = loaders(splits, args.img_size, effective_batch, args.workers)\n\n    model = DefectNet(arch=args.arch, pretrained=True).to(device)\n    feat_dim = model.feat_dim\n    if n_gpu > 1:\n        model = nn.DataParallel(model)\n\n    optimizer = torch.optim.AdamW(model.parameters(), lr=args.lr, weight_decay=0.05)\n    scheduler = torch.optim.lr_scheduler.OneCycleLR(\n        optimizer, max_lr=args.lr, total_steps=args.epochs * len(train_loader), pct_start=0.25\n    )\n    scaler = torch.amp.GradScaler(\"cuda\", enabled=device.type == \"cuda\")\n    criterion = nn.CrossEntropyLoss(label_smoothing=0.05)\n\n    best_f1, best_state = -1.0, None\n    for epoch in range(1, args.epochs + 1):\n        model.train()\n        started, running = time.time(), 0.0\n        for images, labels in train_loader:\n            images = images.to(device, non_blocking=True)\n            labels = labels.to(device, non_blocking=True)\n            optimizer.zero_grad(set_to_none=True)\n            with torch.autocast(\"cuda\", dtype=torch.float16, enabled=device.type == \"cuda\"):\n                loss = criterion(model(images), labels)\n            scaler.scale(loss).backward()\n            scaler.step(optimizer)\n            scaler.update()\n            scheduler.step()\n            running += loss.item()\n\n        logits, labels = evaluate(model, val_loader, device)\n        val = report(logits, labels)\n        print(\n            f\"epoch {epoch:02d}/{args.epochs}  loss={running / len(train_loader):.4f}  \"\n            f\"val_acc={val['accuracy']:.4f}  val_f1={val['macro_f1']:.4f}  \"\n            f\"{time.time() - started:.0f}s\"\n        )\n\n        if val[\"macro_f1\"] > best_f1:\n            best_f1 = val[\"macro_f1\"]\n            core = model.module if isinstance(model, nn.DataParallel) else model\n            best_state = {k: v.detach().cpu().clone() for k, v in core.state_dict().items()}\n\n    core = model.module if isinstance(model, nn.DataParallel) else model\n    core.load_state_dict(best_state)\n\n    val_logits, val_labels = evaluate(model, val_loader, device)\n    temperature = fit_temperature(val_logits, val_labels)\n    print(f\"calibration temperature={temperature:.4f}\")\n\n    # Robustness sweep on the held-out test split, one pass per shifted condition.\n    robustness = {}\n    for condition in CONDITIONS:\n        ds = DefectDataset(splits[\"test\"], build_condition_transform(condition, args.img_size))\n        loader = DataLoader(ds, batch_size=args.batch_size * 2, num_workers=args.workers, pin_memory=True)\n        logits, labels = evaluate(model, loader, device)\n        robustness[condition] = report(logits, labels, temperature)\n        print(\n            f\"  {condition:<18} acc={robustness[condition]['accuracy']:.4f} \"\n            f\"f1={robustness[condition]['macro_f1']:.4f} \"\n            f\"FA={robustness[condition]['false_accept_rate']:.4f} \"\n            f\"FR={robustness[condition]['false_reject_rate']:.4f}\"\n        )\n\n    fit_loader = DataLoader(\n        DefectDataset(splits[\"train\"], build_transforms(args.img_size, train=False)),\n        batch_size=args.batch_size * 2, num_workers=args.workers, pin_memory=True,\n    )\n    means, precision = fit_mahalanobis(model, fit_loader, device, feat_dim)\n\n    out_path = Path(args.out)\n    out_path.parent.mkdir(parents=True, exist_ok=True)\n    torch.save(\n        {\n            \"arch\": args.arch,\n            \"classes\": CLASSES,\n            \"state_dict\": core.state_dict(),\n            \"temperature\": temperature,\n            \"mahalanobis_means\": means.float(),\n            \"mahalanobis_precision\": precision.float(),\n            \"img_size\": args.img_size,\n            \"metrics\": {\"clean_test\": robustness[\"clean\"], \"robustness\": robustness},\n            \"seed\": args.seed,\n        },\n        out_path,\n    )\n    Path(\"models/metrics.json\").write_text(\n        json.dumps({\"robustness\": robustness, \"temperature\": temperature}, indent=2)\n    )\n    print(f\"\\nsaved {out_path}  best_val_f1={best_f1:.4f}\")\n\n\nif __name__ == \"__main__\":\n    main()\n"}""")

